import fs from 'fs';
import path from 'path';
import ts from 'typescript';

export class MissingEntryExportError extends Error {
  constructor(
    public file: string,
    public expectedExport: string
  ) {
    super(`${file} does not export a const named \`${expectedExport}\``);
    this.name = 'MissingEntryExportError';
  }
}

export interface ListSpec {
  name: string;
  dir: string;
  out: string;
  slugOf: (file: string) => string | null;
  render: (slugs: string[], dir: string) => string;
}

const GENERATED_HEADER =
  '// AUTO-GENERATED by scripts/gen-lists.ts, do not edit by hand.\n// Run `pnpm gen:lists` to regenerate.\n';

function kebabToCamel(slug: string): string {
  return slug.replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase());
}

function exportsConst(filePath: string, name: string): boolean {
  const source = ts.createSourceFile(
    filePath,
    fs.readFileSync(filePath, 'utf-8'),
    ts.ScriptTarget.Latest,
    true,
    ts.ScriptKind.TSX
  );
  return source.statements.some(
    (stmt) =>
      ts.isVariableStatement(stmt) &&
      stmt.modifiers?.some((m) => m.kind === ts.SyntaxKind.ExportKeyword) &&
      stmt.declarationList.declarations.some((d) => ts.isIdentifier(d.name) && d.name.text === name)
  );
}

function renderEntries(slugs: string[], dir: string): string {
  const imports: string[] = [];
  const names: string[] = [];
  for (const slug of slugs) {
    const name = `${kebabToCamel(slug)}Entry`;
    if (!exportsConst(path.join(dir, `${slug}.tsx`), name)) {
      throw new MissingEntryExportError(path.join(dir, `${slug}.tsx`), name);
    }
    imports.push(`import { ${name} } from './${slug}';`);
    names.push(`  ${name},`);
  }
  return [
    GENERATED_HEADER,
    `import type { EntrySchema } from '@/playground/lib/types';`,
    ...imports,
    '',
    'export const entries: EntrySchema[] = [',
    ...names,
    '];',
    '',
  ].join('\n');
}

function renderMeta(slugs: string[]): string {
  return JSON.stringify({ title: 'Components', pages: slugs }, null, 2) + '\n';
}

export function createSpecs(wwwRoot: string): ListSpec[] {
  const entriesDir = path.join(wwwRoot, 'playground/entries');
  const docsDir = path.join(wwwRoot, 'docs/content/components');
  return [
    {
      name: 'playground entries',
      dir: entriesDir,
      out: path.join(entriesDir, 'entries.generated.ts'),
      slugOf: (file) =>
        file.endsWith('.tsx') && !file.endsWith('-render.tsx') ? path.basename(file, '.tsx') : null,
      render: renderEntries,
    },
    {
      name: 'docs meta',
      dir: docsDir,
      out: path.join(docsDir, 'meta.json'),
      slugOf: (file) => (file.endsWith('.mdx') ? path.basename(file, '.mdx') : null),
      render: renderMeta,
    },
  ];
}

export function renderList(spec: ListSpec): string {
  const slugs = fs
    .readdirSync(spec.dir)
    .map(spec.slugOf)
    .filter((slug): slug is string => slug !== null)
    .sort((a, b) => a.localeCompare(b));
  return spec.render(slugs, spec.dir);
}

export function generateLists(specs: ListSpec[]): void {
  for (const spec of specs) {
    const next = renderList(spec);
    if (!fs.existsSync(spec.out) || fs.readFileSync(spec.out, 'utf-8') !== next) {
      fs.writeFileSync(spec.out, next);
    }
  }
}
